import ast
from pathlib import Path

p = Path('app/modules/templates/api.py')
mod = ast.parse(p.read_text(encoding='utf-8'))

missing = []
for node in mod.body:
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        is_route = False
        for d in node.decorator_list:
            if isinstance(d, ast.Call) and isinstance(d.func, ast.Attribute):
                if isinstance(d.func.value, ast.Name) and d.func.value.id == 'router':
                    if d.func.attr in ('get', 'post', 'put', 'delete', 'patch'):
                        is_route = True
        if is_route:
            doc = ast.get_docstring(node)
            if not doc or not doc.strip():
                missing.append(node.name)

print('Missing docstrings for route handlers:', missing)
assert not missing, 'Missing docstrings: ' + ', '.join(missing)
print('OK')
PY'
